WITH item_agg AS ( SELECT i.i_item_id, i.i_product_name, i.i_category, i.i_current_price, SUM(wr.wr_return_amt) AS total_return_amt, SUM(wr.wr_return_quantity) AS total_return_qty, SUM(COALESCE(p.p_cost,0)) AS total_promo_cost, COUNT(DISTINCT wp.wp_web_page_id) AS distinct_page_cnt FROM item i JOIN web_returns wr ON wr.wr_item_sk = i.i_item_sk JOIN web_page wp ON wp.wp_web_page_sk = wr.wr_web_page_sk LEFT JOIN promotion p ON p.p_item_sk = i.i_item_sk GROUP BY i.i_item_id, i.i_product_name, i.i_category, i.i_current_price ), ranked_items AS ( SELECT i_item_id, i_product_name, i_category, i_current_price, total_return_amt, total_return_qty, total_promo_cost, distinct_page_cnt, CASE WHEN i_current_price < 20 THEN 'Low Price' WHEN i_current_price BETWEEN 20 AND 100 THEN 'Mid Price' ELSE 'High Price' END AS price_tier, RANK() OVER (PARTITION BY CASE WHEN i_current_price < 20 THEN 'Low Price' WHEN i_current_price BETWEEN 20 AND 100 THEN 'Mid Price' ELSE 'High Price' END ORDER BY total_return_amt DESC) AS price_tier_rank FROM item_agg ) SELECT i_item_id, i_product_name, i_category, i_current_price, total_return_amt, total_return_qty, total_promo_cost, distinct_page_cnt, price_tier, price_tier_rank FROM ranked_items WHERE price_tier_rank <= 10 ORDER BY price_tier, price_tier_rank
